package net.civeira.phylax.features.access.resourceserver.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.resourceserver.domain.ResourceServer;
import net.civeira.phylax.features.access.resourceserver.domain.gateway.ResourceServerCursor;
import net.civeira.phylax.features.access.resourceserver.domain.gateway.ResourceServerFilter;

class ResourceServerSlider extends Slider<ResourceServer> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ResourceServerCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ResourceServerFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ResourceServerFilter, ResourceServerCursor, Iterator<ResourceServer>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ResourceServerSlider(final Iterator<ResourceServer> multi, final int limit,
      final BiFunction<ResourceServerFilter, ResourceServerCursor, Iterator<ResourceServer>> gateway,
      final ResourceServerFilter filter, final ResourceServerCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param resourceServers
   * @param limit
   * @return
   */
  @Override
  public Iterator<ResourceServer> next(List<ResourceServer> resourceServers, int limit) {
    ResourceServer last = resourceServers.get(resourceServers.size() - 1);
    ResourceServerCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
